// 已知亲代加权和有界学习效果纯函数；调用者负责真实亲缘、一次出生和同一随机事务。
#include "birth_endowment.hpp"
#include "resident/domains/growth/growth_skill_api.hpp"
#include <algorithm>
#include <set>
namespace hanmo::resident {namespace {
// 所有概率先限每项再求和，避免坏作者值溢出或负概率悄悄改变抽样。
template<class Values>bool distribution(const Values& values){Integer total=0;for(auto value:values){if(value<0||value>10000)return false;total+=value;}return total==10000;}
// 未知亲代资料保持未知，已知两位必须是不同的真实身份引用。
Status parents(const InnateParentSource& first,const InnateParentSource& second){for(const auto* parent:{&first,&second}){if(parent->actor_id&&(parent->actor_id->empty()||parent->actor_id->size()>256))return common_failure("InvalidInnateParent");if(parent->level&&(!parent->actor_id||*parent->level<0||*parent->level>3))return common_failure("InvalidInnateParentLevel");}return first.actor_id&&second.actor_id&&first.actor_id==second.actor_id?common_failure("DuplicateInnateParent"):common_success();}
// 分布内核只接已核过的有限策略；未记录的一方不会被计算为已知0档。
InnateDistribution calculate(const BirthEndowmentPolicy& policy,const InnateParentSource& first,const InnateParentSource& second){InnateDistribution out;out.both_parent_levels_known=first.level&&second.level;const auto a=first.level.value_or(0),b=second.level.value_or(0),maximum=std::max(a,b);if(maximum==0){out.branch=out.both_parent_levels_known?"known_zero":"unweighted_unknown";out.basis_points=policy.unweighted;return out;}const InnateInheritanceWeights* weights=nullptr;if(a>0&&b>0){if(a==b){out.branch="equal_positive";weights=&policy.same;}else{out.branch="different_positive";weights=&policy.different;}}else{out.branch="single_positive";weights=&policy.single;}out.basis_points[0]=weights->absent;out.basis_points[maximum]+=weights->retained;out.basis_points[std::min<Integer>(3,maximum+1)]+=weights->strengthened;return out;}
// 纯计算需要同一策略结构；完整目录入口另外核扩展技能模式。
Status policy_shape(const BirthEndowmentPolicy& p){if(p.version!="innate_birth_v1"||p.families.empty()||p.families.size()>16||!distribution(p.unweighted))return common_failure("InvalidBirthEndowmentPolicy");for(const auto* weights:{&p.single,&p.different,&p.same})if(!distribution(std::array<Integer,3>{{weights->absent,weights->retained,weights->strengthened}}))return common_failure("InvalidInnateInheritanceWeights");for(const auto& row:p.families.rows()){const auto& family=row.second;if(row.first!=family.id||family.id.empty()||family.id.size()>256||family.learning_skill_ids.empty()||family.learning_skill_ids.size()>16||std::set<StableId>(family.learning_skill_ids.begin(),family.learning_skill_ids.end()).size()!=family.learning_skill_ids.size()||family.learning_bonus_bp[0]!=0)return common_failure("InvalidInnateFamily",row.first);for(std::size_t i=1;i<4;++i)if(family.learning_bonus_bp[i]<family.learning_bonus_bp[i-1]||family.learning_bonus_bp[i]>1500)return common_failure("InvalidInnateLearningBonus",row.first);}return common_success();}
}
Status validate_birth_endowment_policy(const BirthEndowmentPolicy& policy,bool extended){auto valid=policy_shape(policy);if(!valid.ok)return valid;const auto skills=growth_skill_ids(extended);for(const auto& row:policy.families.rows())for(const auto& skill:row.second.learning_skill_ids)if(std::find(skills.begin(),skills.end(),skill)==skills.end())return common_failure("UnknownInnateLearningSkill",skill);return common_success();}
Outcome<InnateDistribution> preview_birth_innate_distribution(const BirthEndowmentPolicy& policy,const StableId& family,const InnateParentSource& first,const InnateParentSource& second){auto valid=policy_shape(policy);if(!valid.ok)return {false,{},valid.error};valid=parents(first,second);if(!valid.ok)return {false,{},valid.error};if(!policy.families.find(family))return {false,{},common_failure("UnknownInnateFamily",family).error};return {true,calculate(policy,first,second),{}};}
Outcome<BirthInnateResult> resolve_birth_innate_draw(const BirthEndowmentPolicy& policy,const StableId& family,const InnateParentSource& first,const InnateParentSource& second,Integer draw){if(draw<0||draw>=10000)return {false,{},common_failure("InvalidInnateDraw").error};auto preview=preview_birth_innate_distribution(policy,family,first,second);if(!preview.ok)return {false,{},preview.error};Integer accumulated=0;for(Integer level=0;level<4;++level){accumulated+=preview.value.basis_points[level];if(draw<accumulated)return {true,{family,policy.version,first,second,preview.value.branch,draw,level,{}},{}};}return {false,{},common_failure("InvalidInnateDistribution").error};}
Status validate_birth_innate_result(const BirthEndowmentPolicy& policy,const BirthInnateResult& result){auto expected=resolve_birth_innate_draw(policy,result.family_id,result.first,result.second,result.draw);if(!expected.ok)return {false,{},expected.error};return result.policy_version==expected.value.policy_version&&result.branch==expected.value.branch&&result.level==expected.value.level?common_success():common_failure("BirthInnateResultMismatch");}
Outcome<Integer> birth_innate_learning_bonus(const BirthEndowmentPolicy& policy,const OrderedTable<Integer>& levels,const StableId& skill){auto valid=policy_shape(policy);if(!valid.ok)return {false,{},valid.error};const auto skills=growth_skill_ids(true);if(std::find(skills.begin(),skills.end(),skill)==skills.end())return {false,0,common_failure("UnknownInnateLearningSkill",skill).error};Integer bonus=0;for(const auto& row:levels.rows()){const auto* family=policy.families.find(row.first);if(!family||row.second<0||row.second>3)return {false,0,common_failure("InvalidInnateLevel",row.first).error};if(std::find(family->learning_skill_ids.begin(),family->learning_skill_ids.end(),skill)!=family->learning_skill_ids.end())bonus+=family->learning_bonus_bp[row.second];}return {true,std::min<Integer>(1500,bonus),{}};}
}
